const app=document.querySelector('#app');const toast=document.querySelector('#toast');
const state={role:'buyer',roleSelected:false,authenticated:false,darkMode:false,sidebarOpen:true,loginStep:1,view:'dashboard',wizard:1,product:'Tomate',quantity:20,price:5.8,days:['Ter','Qui','Sáb'],cart:[],selectedOffer:null,orders:[{buyer:'Restaurante Quintal',product:'Tomate',quantity:'20 kg',status:'Novo'}]};
const offers=[{name:'Tomate',emoji:'🍅',producer:'Sítio Boa Vista',price:5.8,qty:'120 kg',distance:'8 km',harvest:'Hoje',type:'Agricultura familiar'},{name:'Banana prata',emoji:'🍌',producer:'Dona Cida',price:4.2,qty:'80 kg',distance:'12 km',harvest:'Amanhã',type:'Agroecológico'},{name:'Couve',emoji:'🥬',producer:'Sítio Esperança',price:2.5,qty:'45 maços',distance:'5 km',harvest:'Sex, 28 ago',type:'Orgânico'},{name:'Abacate',emoji:'🥑',producer:'Família Andrade',price:6.9,qty:'60 kg',distance:'18 km',harvest:'Sáb, 29 ago',type:'Agricultura familiar'},{name:'Cenoura',emoji:'🥕',producer:'Sítio Boa Vista',price:3.8,qty:'90 kg',distance:'8 km',harvest:'Hoje',type:'Agricultura familiar'},{name:'Ovos caipiras',emoji:'🥚',producer:'Dona Cida',price:18,qty:'30 dúzias',distance:'12 km',harvest:'Amanhã',type:'Caipira'}];
const icon=name=>`<i data-lucide="${name}"></i>`;const money=value=>`R$ ${value.toFixed(2).replace('.',',')}`;
function notify(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
function render(){app.innerHTML=state.authenticated?(state.role==='producer'?producerApp():state.role==='admin'?adminApp():buyerApp()):loginScreen();document.body.classList.toggle('sidebar-hidden',state.authenticated&&!state.sidebarOpen);document.body.classList.toggle('dark-mode',state.darkMode);app.insertAdjacentHTML('afterbegin',`<button class="theme-toggle" data-action="toggle-theme" aria-label="${state.darkMode?'Ativar modo claro':'Ativar modo escuro'}" title="${state.darkMode?'Modo claro':'Modo escuro'}">${icon(state.darkMode?'sun':'moon')}</button>`);if(state.authenticated)app.insertAdjacentHTML('afterbegin',`<button class="sidebar-float" data-action="toggle-sidebar" aria-label="${state.sidebarOpen?'Ocultar':'Mostrar'} barra lateral" title="${state.sidebarOpen?'Ocultar':'Mostrar'} barra lateral">${icon(state.sidebarOpen?'panel-left-close':'panel-left-open')}</button>`);if(window.lucide)lucide.createIcons()}
function loginScreen(){if(!state.roleSelected)return roleSelection();const producer=state.role==='producer';const admin=state.role==='admin';const title=producer?(state.loginStep===1?'Entre com seu e-mail':'Digite o código recebido'):admin?'Acesso administrativo':'Acesse sua conta';const subtitle=producer?(state.loginStep===1?'Informe seu e-mail para receber um código pelo WhatsApp.':'Enviamos um código de 4 números para o seu WhatsApp.') : admin?'Área restrita para a equipe Rural Link.':'Entre para acompanhar suas compras locais.';return `<main class="login-page"><div class="login-card"><div class="brand login-brand"><span class="brand-mark">${icon('sprout')}</span> ruralLINK</div><div class="login-kicker">${icon(producer?'phone':admin?'shield-check':'store')} ${producer?'Acesso do produtor':admin?'Equipe Rural Link':'Área do comprador'}</div><h1>${title}</h1><p class="muted">${subtitle}</p>${producer?producerLoginForm():professionalLoginForm(admin)}<button class="button ghost full change-role" data-action="change-role">${icon('arrow-left')} Escolher outra modalidade</button></div></main>`}
function roleSelection(){return `<main class="login-page role-page"><div class="role-welcome"><div class="brand login-brand"><span class="brand-mark">${icon('sprout')}</span> ruralLINK</div><span class="login-kicker">${icon('map-pin')} Viçosa e região</span><h1>Como você participa?</h1><p class="muted">Escolha uma opção para entrar na área certa da Rural Link.</p><div class="role-options"><button class="role-option" data-select-role="buyer"><span class="role-icon">${icon('store')}</span><strong>Sou comprador</strong><small>Encontro produtos locais para meu negócio.</small></button><button class="role-option" data-select-role="producer"><span class="role-icon">${icon('sprout')}</span><strong>Sou produtor</strong><small>Publico minha colheita e recebo pedidos.</small></button><button class="role-option" data-select-role="admin"><span class="role-icon">${icon('shield-check')}</span><strong>Sou administrador</strong><small>Cuido da operação da plataforma.</small></button></div></div></main>`}
function producerLoginForm(){return state.loginStep===1?`<label>Número de telefone</label><input class="field full login-input" type="tel" inputmode="numeric" maxlength="15" autocomplete="tel" placeholder="(31) 99999-1234" data-login-input="phone"><button class="button large full" data-action="send-code">Receber código ${icon('message-circle')}</button><p class="login-note">Digite apenas números. Os parênteses e o hífen aparecem automaticamente.</p>`:`<label>Código de 4 números</label><input class="field full login-input code-input" inputmode="numeric" maxlength="4" placeholder="• • • •" data-login-input="code"><button class="button large full" data-action="verify-code">Entrar ${icon('arrow-right')}</button><button class="button ghost full" data-action="back-login">Voltar e corrigir telefone</button><p class="login-note">Código simulado: qualquer sequência com 4 números funciona.</p>`}
function professionalLoginForm(admin){return `<label>${admin?'E-mail corporativo':'E-mail'}</label><input class="field full login-input" type="email" placeholder="${admin?'equipe@rurallink.com.br':'compras@seurestaurante.com.br'}" data-login-input="email"><label>${admin?'Senha':'Senha'}</label><input class="field full login-input" type="password" placeholder="Digite sua senha" data-login-input="password"><button class="button large full" data-action="login">${admin?'Entrar no painel':'Entrar'} ${icon('arrow-right')}</button><p class="login-note">Login simulado para demonstração do protótipo.</p>`}
function shell(content,title,nav){const bottomNav=state.role==='admin'?nav:nav.slice(0,4);return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('sprout')}</span> ruralLINK</div><p class="role-label">${state.role==='admin'?'Operação':state.role==='producer'?'Área do produtor':'Área do comprador'}</p><nav class="side-nav">${nav.map(item=>`<button class="${state.view===item[0]?'active':''}" data-view="${item[0]}">${icon(item[2])}<span>${item[1]}</span></button>`).join('')}</nav><div class="side-bottom">Viçosa e cidades próximas<br><strong>● Operação normal</strong></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${state.role==='admin'?'Visão geral':`Bom dia, ${state.role==='producer'?'José':'Mariana'}`}</div><h1>${title}</h1></div><button class="button ghost logout-button" data-action="logout">${icon('log-out')} Sair</button></header>${content}<nav class="bottom-nav">${bottomNav.map(item=>`<button class="${state.view===item[0]?'active':''}" data-view="${item[0]}">${icon(item[2])}<span>${item[1]}</span></button>`).join('')}</nav></main></div>`}
function producerApp(){if(state.view==='wizard')return producerWizard();if(state.view==='orders')return shell(producerOrders(),'Pedidos recebidos',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);if(state.view==='products')return shell(producerProducts(),'Meus produtos',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);if(state.view==='profile')return shell(profile('produtor'),'Meu perfil',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);return shell(producerHome(),'Minha colheita',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']])}
function productItems(){return[{name:'Tomate',emoji:'🍅',qty:'120 kg',status:'Disponível',price:'R$ 5,80/kg'},{name:'Couve',emoji:'🥬',qty:'45 maços',status:'Disponível',price:'R$ 2,50/maço'},{name:'Abacate',emoji:'🥑',qty:'0 kg',status:'Vendido',price:'R$ 6,90/kg'}]}
function productCard(p){return `<article class="product-card"><div class="product-visual">${p.emoji}</div><div class="product-info"><div class="row"><h3>${p.name}</h3><span class="tag ${p.status==='Vendido'?'red':''}">${p.status}</span></div><div class="meta"><span>${p.qty} restantes</span><strong>${p.price}</strong></div></div></article>`}
function producerHome(){return `<section class="content"><div class="hero"><div><span class="tag orange">${icon('map-pin')} Viçosa, MG</span><h2>O que você colheu hoje?</h2><p>Publique em poucos passos e encontre compradores perto de você.</p><br><button class="button large" data-action="wizard">${icon('plus')} Adicionar produto</button></div></div><div class="section-title"><h3>Publicados recentemente</h3><button class="button ghost" data-view="products">Ver todos ${icon('arrow-right')}</button></div><div class="grid grid-3">${productItems().slice(0,3).map(productCard).join('')}</div><div class="panel" style="margin-top:22px"><div class="row"><div><h3>${icon('message-circle')} Você tem um novo pedido</h3><p class="muted">Restaurante Quintal quer comprar 20 kg de tomate.</p></div><button class="button secondary" data-view="orders">Ver pedido</button></div></div></section>`}
function producerProducts(){return `<section class="content"><div class="row" style="margin-bottom:20px"><p class="muted">3 produtos publicados</p><button class="button" data-action="wizard">${icon('plus')} Novo produto</button></div><div class="grid grid-3">${productItems().map(productCard).join('')}</div></section>`}
function producerOrders(){return `<section class="content"><div class="panel"><div class="panel-header"><div><h3>Solicitações de compra</h3><p class="muted">Avisos importantes também chegam pelo WhatsApp.</p></div><span class="tag orange">${icon('bell')} 1 novo</span></div><div class="list">${state.orders.map((o,i)=>`<div class="list-item"><div class="list-icon">🍅</div><div class="grow"><strong>${o.buyer}</strong><div class="muted">${o.product} · ${o.quantity}</div></div><span class="tag ${o.status==='Novo'?'orange':''}">${o.status}</span><button class="button secondary" data-action="order" data-index="${i}">Detalhes</button></div>`).join('')}</div></div></section>`}
function producerWizard(){const steps=['Categoria','Quantidade','Preço','Disponibilidade','Confirmar'];let body;if(state.wizard===1)body=`<p class="muted">Escolha uma opção. Você não precisa digitar.</p><div class="choice-grid">${[['Tomate','🍅'],['Banana','🍌'],['Couve','🥬'],['Abacate','🥑'],['Cenoura','🥕'],['Outro','＋']].map(x=>`<button class="choice ${state.product===x[0]?'selected':''}" data-product="${x[0]}"><span class="emoji">${x[1]}</span>${x[0]}</button>`).join('')}</div>`;else if(state.wizard===2)body=`<p class="muted">Ajuste a quantidade de ${state.product.toLowerCase()} disponível.</p><div class="number-control"><button data-action="minus">−</button><span class="number-value">${state.quantity}<small style="font-size:18px"> kg</small></span><button data-action="plus">＋</button></div><label class="muted">Ou digite outro valor</label><input class="field full" type="number" value="${state.quantity}" data-input="quantity">`;else if(state.wizard===3)body=`<p class="muted">Referência para Viçosa e região: R$ 5,80/kg</p><div style="margin:35px 0"><label>Seu preço por kg</label><input class="field full" style="font-size:30px;height:65px;margin-top:8px" value="${state.price.toFixed(2).replace('.',',')}" data-input="price"></div><span class="tag">${icon('trending-up')} Preço dentro da média local</span>`;else if(state.wizard===4)body=`<p class="muted">Marque os dias em que você consegue colher e entregar.</p><div class="days">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map((d,i)=>`<button class="day ${state.days.includes(d)?'selected':''}" data-day="${d}"><strong>${d}</strong><small>${26+i}</small></button>`).join('')}</div>`;else body=`<div class="panel" style="box-shadow:none;background:#f7fbf5"><div class="product-visual" style="height:130px">${offers.find(x=>x.name===state.product)?.emoji||'🌱'}</div><div class="row" style="margin-top:17px"><div><h3>${state.product}</h3><p class="muted">${state.quantity} kg · ${state.days.join(', ')}</p></div><span class="price">${money(state.price)}/kg</span></div></div>`;return `<main class="content"><div class="wizard"><div class="wizard-top"><button class="close" data-action="home">${icon('x')} Fechar</button><div class="progress">${steps.map((_,i)=>`<span class="${i<state.wizard?'on':''}"></span>`).join('')}</div><span class="muted">${state.wizard}/5</span></div><h2>${['O que você colheu?','Quanto você tem de '+state.product+'?','Defina seu preço','Quando pode entregar?','Confira seu anúncio'][state.wizard-1]}</h2>${body}<div class="wizard-actions">${state.wizard>1?'<button class="button ghost" data-action="back">Voltar</button>':'<span></span>'}${state.wizard<5?`<button class="button" data-action="next">Avançar ${icon('arrow-right')}</button>`:`<button class="button large" data-action="publish">${icon('check')} Publicar agora</button>`}</div></div></main>`}
function buyerApp(){if(state.view==='catalog')return shell(catalog(),'Buscar ofertas',[['dashboard','Início','layout-dashboard'],['catalog','Buscar','search'],['cart','Carrinho '+(state.cart.length?`(${state.cart.length})`:''),'shopping-basket'],['recurring','Recorrência','calendar-days'],['profile','Perfil','user-round']]);if(state.view==='cart')return shell(cart(),'Seu carrinho',[['dashboard','Início','layout-dashboard'],['catalog','Buscar','search'],['cart','Carrinho '+(state.cart.length?`(${state.cart.length})`:''),'shopping-basket'],['recurring','Recorrência','calendar-days'],['profile','Perfil','user-round']]);if(state.view==='recurring')return shell(recurring(),'Compras recorrentes',[['dashboard','Início','layout-dashboard'],['catalog','Buscar','search'],['cart','Carrinho '+(state.cart.length?`(${state.cart.length})`:''),'shopping-basket'],['recurring','Recorrência','calendar-days'],['profile','Perfil','user-round']]);if(state.view==='profile')return shell(profile('comprador'),'Perfil da empresa',[['dashboard','Início','layout-dashboard'],['catalog','Buscar','search'],['cart','Carrinho '+(state.cart.length?`(${state.cart.length})`:''),'shopping-basket'],['recurring','Recorrência','calendar-days'],['profile','Perfil','user-round']]);return shell(buyerDashboard(),'Painel de compras',[['dashboard','Início','layout-dashboard'],['catalog','Buscar','search'],['cart','Carrinho '+(state.cart.length?`(${state.cart.length})`:''),'shopping-basket'],['recurring','Recorrência','calendar-days'],['profile','Perfil','user-round']])}
function offerCard(o){return `<article class="product-card"><div class="product-visual">${o.emoji}</div><div class="product-info"><div class="row"><h3>${o.name}</h3><span class="tag">${o.distance}</span></div><p class="muted">${o.producer} · ${o.qty}</p><div class="row"><span class="price">${money(o.price)}<small>/kg</small></span><button class="button secondary" data-offer="${o.name}">Ver oferta</button></div></div></article>`}
function buyerDashboard(){return `<section class="content"><div class="hero"><div><span class="tag orange">${icon('sun')} Sazonal agora</span><h2>Colheita da semana na sua região</h2><p>Ingredientes frescos, de quem produz perto da sua cozinha.</p><br><button class="button large" data-view="catalog">${icon('search')} Explorar ofertas</button></div></div><div class="section-title"><h3>Colheita da semana</h3><button class="button ghost" data-view="catalog">Ver catálogo ${icon('arrow-right')}</button></div><div class="grid grid-3">${offers.slice(0,3).map(offerCard).join('')}</div><div class="grid grid-2" style="margin-top:22px"><div class="panel"><div class="panel-header"><div><h3>${icon('zap')} Excedentes disponíveis</h3><p class="muted">Oportunidades com preço especial hoje.</p></div><span class="tag orange">-20%</span></div><div class="list-item"><div class="list-icon">🥕</div><div class="grow"><strong>Cenoura</strong><div class="muted">Sítio Boa Vista · 90 kg</div></div><strong class="price">R$ 3,80/kg</strong></div></div><div class="panel"><h3>${icon('repeat')} Próximas compras</h3><p class="muted">Sua lista recorrente está ativa.</p><div class="row"><strong>Quintas-feiras</strong><span class="tag">3 itens</span></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><button class="button secondary full" data-view="recurring">Gerenciar recorrência</button></div></div></section>`}
function catalog(){return `<section class="content"><div class="row"><div><h2>Encontre ingredientes locais</h2><p class="muted">Compare preço, distância e disponibilidade em uma única tela.</p></div><span class="tag">${icon('map-pin')} Até 20 km de Viçosa</span></div><div class="filters"><input class="field" placeholder="Buscar produto..." data-filter="text"><select class="select"><option>Todos os tipos</option><option>Orgânico</option><option>Agricultura familiar</option></select><select class="select"><option>Qualquer distância</option><option>Até 10 km</option><option>Até 20 km</option></select><button class="button secondary">${icon('sliders-horizontal')} Filtros</button></div><div class="grid grid-3" id="offer-list">${offers.map(offerCard).join('')}</div></section>`}
function cart(){const total=state.cart.reduce((sum,item)=>sum+item.price*item.quantity,0);return `<section class="content"><div class="row" style="margin-bottom:20px"><div><h2>Seu carrinho</h2><p class="muted">Itens de diferentes produtores, juntos no mesmo pedido.</p></div><span class="tag">${state.cart.length} itens</span></div>${state.cart.length?`<div class="grid grid-2"><div class="panel"><h3>Itens por produtor</h3><div class="list">${state.cart.map((item,i)=>`<div class="list-item"><div class="list-icon">${item.emoji}</div><div class="grow"><strong>${item.producer}</strong><div class="muted">${item.name} · ${item.quantity} kg × ${money(item.price)}</div></div><strong>${money(item.price*item.quantity)}</strong><button class="button ghost" data-remove="${i}">${icon('trash-2')}</button></div>`).join('')}</div></div><div class="panel"><span class="muted">Total estimado</span><div style="font:700 34px 'Space Grotesk';margin:8px 0 20px">${money(total)}</div><p class="muted">Entrega direta dos produtores. Endereço: Rua Gomes Barbosa, 120, Centro.</p><button class="button large full" data-action="checkout">Finalizar pedido ${icon('arrow-right')}</button></div></div>`:`<div class="panel" style="text-align:center;padding:70px 20px"><div style="font-size:50px">🧺</div><h3>Seu carrinho está vazio</h3><p class="muted">Escolha uma oferta para começar sua compra.</p><button class="button" data-view="catalog">Explorar catálogo</button></div>`}</section>`}
function recurring(){return `<section class="content"><div class="panel"><div class="panel-header"><div><h3>Minha lista semanal</h3><p class="muted">Toque em um dia para ajustar produtos e quantidades.</p></div><span class="tag">Ativa</span></div><div class="list">${['Segunda','Terça','Quarta','Quinta','Sexta'].map((day,i)=>`<div class="list-item"><div class="list-icon">${icon('calendar-days')}</div><div class="grow"><strong>${day}</strong><div class="muted">${i===3?'Tomate 20 kg · Couve 10 maços · Ovos 2 dúzias':'Nenhum pedido programado'}</div></div><button class="button ${i===3?'secondary':'ghost'}" data-action="recurring">${i===3?'Editar':'Adicionar'}</button></div>`).join('')}</div></div></section>`}
function profile(type){return `<section class="content"><div class="grid grid-2"><div class="panel"><h3>Dados ${type==='produtor'?'do produtor':'do estabelecimento'}</h3><label>Nome</label><input class="field full" style="margin:7px 0 14px" value="${type==='produtor'?'José Silva':'Restaurante Quintal'}"><label>${type==='produtor'?'Telefone':'Endereço de entrega'}</label><input class="field full" style="margin:7px 0 14px" value="${type==='produtor'?'+55 31 99999-1234':'Rua Gomes Barbosa, 120, Centro'}"><button class="button" data-action="save">Salvar alterações</button></div><div class="panel"><h3>Atalhos</h3><div class="list"><button class="list-item" data-action="save"><div class="list-icon">${icon('credit-card')}</div><div class="grow"><strong>Forma de pagamento</strong><div class="muted">${type==='produtor'?'Pix, dinheiro':'Pix · final 4821'}</div></div>${icon('chevron-right')}</button><button class="list-item" data-action="save"><div class="list-icon">${icon('history')}</div><div class="grow"><strong>Histórico de pedidos</strong></div>${icon('chevron-right')}</button><button class="list-item" data-action="save"><div class="list-icon">${icon('log-out')}</div><div class="grow"><strong>Sair da conta</strong></div>${icon('chevron-right')}</button></div></div></div></section>`}
function adminApp(){const nav=[['dashboard','Dashboard','layout-dashboard'],['users','Cadastros','users'],['moderation','Moderação','shield-check'],['routes','Rotas','route'],['production','Produção local','sprout']];if(state.view==='users')return shell(adminUsers(),'Cadastros pendentes',nav);return shell(adminDashboard(),'Visão geral',nav)}
function adminDashboard(){return `<section class="content"><div class="grid grid-3"><div class="panel stat"><span class="muted">Produtores ativos</span><strong>248</strong><span class="trend">↑ 12% este mês</span></div><div class="panel stat"><span class="muted">Compradores ativos</span><strong>86</strong><span class="trend">↑ 8% este mês</span></div><div class="panel stat"><span class="muted">Volume transacionado</span><strong>R$ 184,2k</strong><span class="trend">↑ 21% este mês</span></div></div><div class="grid grid-2" style="margin-top:22px"><div class="panel"><div class="panel-header"><div><h3>Movimentação da plataforma</h3><p class="muted">Últimos 30 dias · Viçosa e região</p></div><span class="tag">+21%</span></div><div class="chart">${[35,48,40,64,57,73,85,68,92,78].map(h=>`<span class="bar" style="height:${h}%"></span>`).join('')}</div></div><div class="panel"><div class="panel-header"><div><h3>Precisa de atenção</h3><p class="muted">Itens aguardando ação da equipe.</p></div><span class="tag orange">7 itens</span></div><div class="list"><div class="list-item"><div class="list-icon">👤</div><div class="grow"><strong>5 cadastros</strong><div class="muted">Aguardando aprovação</div></div><button class="button secondary" data-view="users">Revisar</button></div><div class="list-item"><div class="list-icon">⚠️</div><div class="grow"><strong>2 anúncios</strong><div class="muted">Preço fora do padrão</div></div><button class="button secondary" data-view="moderation">Revisar</button></div></div></div></div></section>`}
function adminUsers(){return `<section class="content"><div class="panel"><div class="panel-header"><div><h3>Cadastros aguardando aprovação</h3><p class="muted">Verifique os dados antes de liberar o acesso à plataforma.</p></div><span class="tag orange">5 pendentes</span></div>${['Sítio Sol Nascente','Horta da Serra','Pousada Recanto'].map((name,i)=>`<div class="list-item"><div class="list-icon">${i?'🌱':'👤'}</div><div class="grow"><strong>${name}</strong><div class="muted">Produtor · Viçosa, MG · enviado há ${i+1}h</div></div><button class="button secondary" data-action="approve">Aprovar</button><button class="button ghost" data-action="reject">Reprovar</button></div>`).join('')}</div></section>`}

app.addEventListener('click',event=>{const view=event.target.closest('[data-view]')?.dataset.view;if(view){state.view=view;render();return}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='wizard'){state.view='wizard';state.wizard=1;render()}if(action==='home'){state.view=state.role==='producer'?'home':'dashboard';render()}if(action==='next'){state.wizard=Math.min(5,state.wizard+1);render()}if(action==='back'){state.wizard=Math.max(1,state.wizard-1);render()}if(action==='plus'){state.quantity+=10;render()}if(action==='minus'){state.quantity=Math.max(1,state.quantity-10);render()}if(action==='publish'){state.view='home';notify('Produto publicado. Os compradores da região já podem encontrá-lo.');render()}if(action==='checkout'){state.cart=[];state.view='dashboard';notify('Pedido confirmado. Os produtores receberam a solicitação.');render()}if(action==='approve'){event.target.closest('.list-item').remove();notify('Cadastro aprovado com sucesso.')}if(action==='reject'){event.target.closest('.list-item').remove();notify('Cadastro marcado para revisão.')}if(action==='save'){notify('Alterações salvas.')}if(action==='order'){const index=event.target.closest('[data-index]')?.dataset.index;const order=state.orders[index];if(order.status==='Novo'){order.status='Aceito';notify('Pedido aceito. Endereço de entrega liberado.');render()}}if(action==='recurring'){notify('Editor de recorrência aberto.')}const product=event.target.closest('[data-product]')?.dataset.product;if(product){state.product=product;state.wizard=2;render()}const day=event.target.closest('[data-day]')?.dataset.day;if(day){state.days=state.days.includes(day)?state.days.filter(item=>item!==day):[...state.days,day];render()}const offerName=event.target.closest('[data-offer]')?.dataset.offer;if(offerName){const offer=offers.find(item=>item.name===offerName);state.cart.push({...offer,quantity:offer.name==='Couve'?10:20});notify(`${offer.name} adicionado ao carrinho.`);render()}const remove=event.target.closest('[data-remove]')?.dataset.remove;if(remove!==undefined){state.cart.splice(Number(remove),1);render()}});
app.addEventListener('change',event=>{if(event.target.matches('[data-role]')){state.role=event.target.value;state.view=state.role==='producer'?'home':state.role==='admin'?'dashboard':'dashboard';render()}if(event.target.matches('[data-input="quantity"]'))state.quantity=Number(event.target.value)||1;if(event.target.matches('[data-input="price"]'))state.price=Number(event.target.value.replace(',','.'))||state.price});
app.addEventListener('change',event=>{if(event.target.matches('[data-login-role]')){state.role=event.target.value;state.loginStep=1;render()}});
app.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(action==='send-code'){state.loginStep=2;notify('Código enviado pelo WhatsApp.');render()}if(action==='verify-code'){state.authenticated=true;state.view='home';notify('Acesso liberado.');render()}if(action==='login'){state.authenticated=true;state.view='dashboard';notify('Acesso liberado.');render()}if(action==='back-login'){state.loginStep=1;render()}});
app.addEventListener('click',event=>{const role=event.target.closest('[data-select-role]')?.dataset.selectRole;if(role){state.role=role;state.roleSelected=true;state.loginStep=1;render()}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='change-role'){state.roleSelected=false;state.loginStep=1;render()}if(action==='toggle-theme'){state.darkMode=!state.darkMode;render()}if(action==='toggle-sidebar'){state.sidebarOpen=!state.sidebarOpen;render()}if(action==='logout'){state.authenticated=false;state.roleSelected=false;state.sidebarOpen=true;state.loginStep=1;state.view='dashboard';notify('Sessão encerrada.');render()}});
function formatPhone(value){const digits=value.replace(/\D/g,'').slice(0,11);if(digits.length<=2)return digits?`(${digits}`:'';const area=digits.slice(0,2);const number=digits.slice(2);if(number.length<=5)return `(${area}) ${number}`;return `(${area}) ${number.slice(0,5)}-${number.slice(5)}`}
app.addEventListener('input',event=>{if(event.target.matches('[data-login-input="phone"]'))event.target.value=formatPhone(event.target.value)});

const productStorageKey='rurallink-products';
const productEmoji={Tomate:'🍅',Banana:'🍌',Couve:'🥬',Abacate:'🥑',Cenoura:'🥕',Ovos:'🥚'};
function readProducts(){try{return JSON.parse(localStorage.getItem(productStorageKey)||'[]')}catch(error){return[]}}
function backendServices(){return window.RuralLink?.services}
function writeProducts(products,options={}){localStorage.setItem(productStorageKey,JSON.stringify(products));if(options.sync===false)return;const services=backendServices();if(!services)return;services.produtoService.list().then(async remote=>{const desired=new Set(products.map(product=>product.id));for(const product of products){try{await services.produtoService.update(product.id,product)}catch(error){if(error.status===404)await services.produtoService.create(product)}}for(const product of remote.filter(item=>!desired.has(item.id)))await services.produtoService.remove(product.id)}).catch(()=>{})}
function productUnitLabel(unit){return unit||'kg'}
function productOffer(product){return{name:product.name,emoji:productEmoji[product.name]||'🌱',producer:product.producer||'Produtor local',price:Number(product.price)||0,qty:`${product.quantity} ${productUnitLabel(product.unit)}`,distance:'Viçosa',harvest:product.harvest||'A combinar',type:'Produção local',description:product.description||'',productId:product.id,unit:productUnitLabel(product.unit)}}
function availableOffers(){return[...offers.filter(offer=>!offer.productId),...readProducts().map(productOffer)]}
function currentProducerProducts(){return readProducts().filter(product=>product.producerEmail===state.producerEmail)}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[character]))}
function producerLoginForm(){return state.loginStep===1?`<label>E-mail</label><input class="field full login-input" type="email" autocomplete="email" placeholder="produtor@rurallink.com.br" data-login-input="email"><button class="button large full" data-action="send-code">Receber código ${icon('message-circle')}</button><p class="login-note">Você vai receber um código pelo WhatsApp.</p>`:`<label>Código do WhatsApp</label><input class="field full login-input code-input" inputmode="numeric" maxlength="4" placeholder="• • • •" data-login-input="code"><button class="button large full" data-action="verify-code">Entrar ${icon('arrow-right')}</button><button class="button ghost full" data-action="back-login">Voltar e corrigir e-mail</button><p class="login-note">Código simulado: qualquer sequência com 4 números funciona.</p>`}
function productItems(){return currentProducerProducts().map(product=>({id:product.id,name:product.name,emoji:productEmoji[product.name]||'🌱',qty:`${product.quantity} ${productUnitLabel(product.unit)}`,status:Number(product.quantity)>0?'Disponível':'Vendido',price:`${money(Number(product.price)||0)}/${productUnitLabel(product.unit)}`,harvest:product.harvest,description:product.description}))}
function productCard(product){return`<article class="product-card"><div class="product-visual">${product.emoji||'🌱'}</div><div class="product-info"><div class="row"><h3>${escapeHtml(product.name)}</h3><span class="tag ${product.status==='Vendido'?'red':''}">${product.status||'Disponível'}</span></div><div class="meta"><span>${escapeHtml(product.qty||`${product.quantity} ${productUnitLabel(product.unit)}`)} restantes</span><strong>${escapeHtml(product.price||money(Number(product.price)||0))}</strong></div>${product.harvest?`<p class="muted" style="margin:10px 0 0">Próxima colheita: ${escapeHtml(product.harvest)}</p>`:''}<div class="row" style="margin-top:14px"><button class="button secondary" data-action="edit-product" data-product-id="${product.id}">${icon('pencil')} Editar</button><button class="button ghost" data-action="delete-product" data-product-id="${product.id}">${icon('trash-2')} Excluir</button></div></div></article>`}
function productForm(){const product=readProducts().find(item=>item.id===state.editingProductId)||{name:'',quantity:'',unit:'kg',price:'',harvest:'',description:''};const editing=Boolean(state.editingProductId);return`<section class="content"><div class="panel" style="max-width:760px;margin:0 auto"><div class="panel-header"><div><h3>${editing?'Editar produto':'Cadastrar produto'}</h3><p class="muted">Informe os dados da sua produção para os compradores da região.</p></div><button class="button ghost" data-view="products">${icon('x')} Fechar</button></div><form data-product-form><div class="grid grid-2"><div><label>Nome do produto</label><input class="field full" name="name" required value="${escapeHtml(product.name)}" placeholder="Ex.: Tomate"><label>Quantidade disponível</label><input class="field full" name="quantity" type="number" min="0" step="0.01" required value="${escapeHtml(product.quantity)}" placeholder="Ex.: 120"></div><div><label>Unidade</label><select class="select full" name="unit"><option ${product.unit==='kg'?'selected':''}>kg</option><option ${product.unit==='tonelada'?'selected':''}>tonelada</option><option ${product.unit==='saca'?'selected':''}>saca</option><option ${product.unit==='maço'?'selected':''}>maço</option><option ${product.unit==='dúzia'?'selected':''}>dúzia</option></select><label>Preço</label><input class="field full" name="price" type="number" min="0" step="0.01" required value="${escapeHtml(product.price)}" placeholder="Ex.: 5,80"></div></div><label>Data da próxima colheita</label><input class="field full" name="harvest" type="date" value="${escapeHtml(product.harvest)}"><label>Descrição / informações adicionais</label><textarea class="field full" name="description" rows="4" placeholder="Conte algo importante sobre este produto">${escapeHtml(product.description)}</textarea><div class="row" style="margin-top:20px"><button class="button" type="submit" data-action="save-product">${icon('check')} ${editing?'Salvar alterações':'Cadastrar produto'}</button><button class="button ghost" type="button" data-view="products">Cancelar</button></div></form></div></section>`}
function producerProducts(){const products=productItems();return`<section class="content"><div class="row" style="margin-bottom:20px"><p class="muted">${products.length} produto${products.length===1?'':'s'} publicado${products.length===1?'':'s'}</p><button class="button" data-action="wizard">${icon('plus')} Novo produto</button></div>${products.length?`<div class="grid grid-3">${products.map(productCard).join('')}</div>`:`<div class="panel" style="text-align:center;padding:55px 20px"><div style="font-size:50px">🌱</div><h3>Nenhum produto cadastrado</h3><p class="muted">Cadastre sua primeira produção para aparecer no catálogo.</p><button class="button" data-action="wizard">${icon('plus')} Cadastrar produto</button></div>`}</section>`}
function producerHome(){const products=productItems();return`<section class="content"><div class="hero"><div><span class="tag orange">${icon('map-pin')} Viçosa, MG</span><h2>O que você colheu hoje?</h2><p>Publique em poucos passos e encontre compradores perto de você.</p><br><button class="button large" data-action="wizard">${icon('plus')} Adicionar produto</button></div></div><div class="section-title"><h3>Publicados recentemente</h3><button class="button ghost" data-view="products">Ver todos ${icon('arrow-right')}</button></div>${products.length?`<div class="grid grid-3">${products.slice(0,3).map(productCard).join('')}</div>`:`<div class="panel"><p class="muted">Você ainda não publicou produtos.</p></div>`}<div class="panel" style="margin-top:22px"><div class="row"><div><h3>${icon('message-circle')} Você tem um novo pedido</h3><p class="muted">Restaurante Quintal quer comprar 20 kg de tomate.</p></div><button class="button secondary" data-view="orders">Ver pedido</button></div></div></section>`}
function offerCard(offer){return`<article class="product-card"><div class="product-visual">${offer.emoji||'🌱'}</div><div class="product-info"><div class="row"><h3>${escapeHtml(offer.name)}</h3><span class="tag">${escapeHtml(offer.distance||'Viçosa')}</span></div><p class="muted">${escapeHtml(offer.producer)} · ${escapeHtml(offer.qty)}</p><p class="muted">Próxima colheita: ${escapeHtml(offer.harvest||'A combinar')}</p>${offer.description?`<p class="muted">${escapeHtml(offer.description)}</p>`:''}<div class="row"><span class="price">${money(Number(offer.price)||0)}<small>/${escapeHtml(offer.unit||'kg')}</small></span><button class="button secondary" data-offer="${escapeHtml(offer.name)}" ${offer.productId?`data-product-id="${offer.productId}"`:''}>Ver oferta</button></div></div></article>`}
function catalog(){const catalogOffers=availableOffers();return`<section class="content"><div class="row"><div><h2>Encontre ingredientes locais</h2><p class="muted">Compare preço, distância e disponibilidade em uma única tela.</p></div><span class="tag">${icon('map-pin')} Até 20 km de Viçosa</span></div><div class="filters"><input class="field" placeholder="Buscar produto..." data-filter="text"><select class="select"><option>Todos os tipos</option><option>Orgânico</option><option>Agricultura familiar</option></select><select class="select"><option>Qualquer distância</option><option>Até 10 km</option><option>Até 20 km</option></select><button class="button secondary">${icon('sliders-horizontal')} Filtros</button></div><div class="grid grid-3" id="offer-list">${catalogOffers.map(offerCard).join('')}</div></section>`}
function buyerDashboard(){const catalogOffers=availableOffers();return`<section class="content"><div class="hero"><div><span class="tag orange">${icon('sun')} Sazonal agora</span><h2>Colheita da semana na sua região</h2><p>Ingredientes frescos, de quem produz perto da sua cozinha.</p><br><button class="button large" data-view="catalog">${icon('search')} Explorar ofertas</button></div></div><div class="section-title"><h3>Colheita da semana</h3><button class="button ghost" data-view="catalog">Ver catálogo ${icon('arrow-right')}</button></div><div class="grid grid-3">${catalogOffers.slice(0,3).map(offerCard).join('')}</div><div class="grid grid-2" style="margin-top:22px"><div class="panel"><div class="panel-header"><div><h3>${icon('zap')} Excedentes disponíveis</h3><p class="muted">Oportunidades com preço especial hoje.</p></div><span class="tag orange">-20%</span></div><div class="list-item"><div class="list-icon">🥕</div><div class="grow"><strong>Cenoura</strong><div class="muted">Sítio Boa Vista · 90 kg</div></div><strong class="price">R$ 3,80/kg</strong></div></div><div class="panel"><h3>${icon('repeat')} Próximas compras</h3><p class="muted">Sua lista recorrente está ativa.</p><div class="row"><strong>Quintas-feiras</strong><span class="tag">3 itens</span></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><button class="button secondary full" data-view="recurring">Gerenciar recorrência</button></div></div></section>`}
function producerApp(){if(state.view==='product-form')return shell(productForm(),state.editingProductId?'Editar produto':'Novo produto',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);if(state.view==='orders')return shell(producerOrders(),'Pedidos recebidos',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);if(state.view==='products')return shell(producerProducts(),'Meus produtos',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);if(state.view==='profile')return shell(profile('produtor'),'Meu perfil',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']]);return shell(producerHome(),'Minha colheita',[['home','Início','house'],['products','Meus produtos','package'],['orders','Pedidos','inbox'],['profile','Perfil','user-round']])}
app.addEventListener('submit',event=>{if(!event.target.matches('[data-product-form]'))return;event.preventDefault();const form=new FormData(event.target);const products=readProducts();const product={id:state.editingProductId||`product-${Date.now()}`,producerEmail:state.producerEmail||'produtor@rurallink.com.br',producer:'Produtor Rural',name:String(form.get('name')).trim(),quantity:Number(form.get('quantity'))||0,unit:String(form.get('unit')),price:Number(String(form.get('price')).replace(',','.'))||0,harvest:String(form.get('harvest')||''),description:String(form.get('description')||'').trim()};if(!product.name||product.quantity<0||product.price<0){notify('Preencha nome, quantidade e preço.');return}const index=products.findIndex(item=>item.id===product.id);if(index>=0)products[index]=product;else products.push(product);writeProducts(products);state.editingProductId=null;state.view='products';notify(index>=0?'Produto atualizado com sucesso.':'Produto cadastrado com sucesso.');render()});
app.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(action==='wizard'&&state.role==='producer'){state.editingProductId=null;state.view='product-form';render()}if(action==='edit-product'){state.editingProductId=event.target.closest('[data-product-id]').dataset.productId;state.view='product-form';render()}if(action==='delete-product'){const id=event.target.closest('[data-product-id]').dataset.productId;if(confirm('Excluir este produto?')){writeProducts(readProducts().filter(product=>product.id!==id));notify('Produto excluído.');render()}}if(action==='verify-code'&&state.role==='producer'){state.producerEmail=state.producerEmail||'produtor@rurallink.com.br';localStorage.setItem('rurallink-producer-email',state.producerEmail)}});
app.addEventListener('input',event=>{if(event.target.matches('[data-login-input="email"]')&&state.role==='producer')state.producerEmail=event.target.value});
const savedProducerEmail=localStorage.getItem('rurallink-producer-email');if(savedProducerEmail)state.producerEmail=savedProducerEmail;
readProducts().map(productOffer).forEach(product=>{if(!offers.some(offer=>offer.productId===product.productId))offers.push(product)});

const purchaseStorageKey='rurallink-purchases';
function readPurchases(){try{return JSON.parse(localStorage.getItem(purchaseStorageKey)||'[]')}catch(error){return[]}}
function writePurchases(purchases){const previous=readPurchases();localStorage.setItem(purchaseStorageKey,JSON.stringify(purchases));const services=backendServices();if(!services)return;const added=purchases.filter(purchase=>!previous.some(item=>item.id===purchase.id));added.forEach(purchase=>services.compraService.create({buyerEmail:purchase.buyerEmail,productId:purchase.productId,quantity:purchase.quantity}).catch(()=>{}))}
function buyerEmail(){return state.buyerEmail||'comprador@rurallink.com.br'}
function buyerPurchases(){return readPurchases().filter(purchase=>purchase.buyerEmail===buyerEmail())}
function buyerNav(){return[['dashboard','Início','layout-dashboard'],['catalog','Buscar','search'],['cart','Carrinho '+(state.cart.length?`(${state.cart.length})`:''),'shopping-basket'],['purchases','Compras','history'],['recurring','Recorrência','calendar-days'],['profile','Perfil','user-round']]}
function buyerOffer(productId){return availableOffers().find(offer=>offer.productId===productId)}
function offerDetails(){const offer=buyerOffer(state.selectedProductId);if(!offer)return`<section class="content"><div class="panel"><h3>Produto não encontrado</h3><button class="button" data-view="catalog">Voltar ao catálogo</button></div></section>`;const product=readProducts().find(item=>item.id===offer.productId);return`<section class="content"><button class="button ghost" data-view="catalog">${icon('arrow-left')} Voltar ao catálogo</button><div class="grid grid-2" style="margin-top:20px"><div class="panel"><div class="product-visual" style="height:180px">${offer.emoji}</div><h2>${escapeHtml(offer.name)}</h2><p class="muted">${escapeHtml(offer.description||'Produto cadastrado por produtor local.')}</p><div class="list"><div class="list-item"><span class="grow">Produtor</span><strong>${escapeHtml(offer.producer)}</strong></div><div class="list-item"><span class="grow">Disponível</span><strong>${escapeHtml(offer.qty)}</strong></div><div class="list-item"><span class="grow">Preço</span><strong>${money(Number(offer.price)||0)}/${escapeHtml(offer.unit||'kg')}</strong></div><div class="list-item"><span class="grow">Próxima colheita</span><strong>${escapeHtml(offer.harvest||'A combinar')}</strong></div></div></div><div class="panel"><h3>Comprar produto</h3><p class="muted">Informe a quantidade que deseja comprar.</p><label>Quantidade desejada (${escapeHtml(offer.unit||'kg')})</label><input class="field full" type="number" min="0.01" step="0.01" max="${product?product.quantity:0}" value="${product?Math.min(1,product.quantity):0}" data-purchase-quantity><p class="muted" style="margin-top:10px">Estoque disponível: ${escapeHtml(offer.qty)}</p><div class="row" style="margin-top:22px"><strong class="price" data-purchase-total>R$ 0,00</strong><button class="button large" data-action="purchase" data-product-id="${offer.productId}">${icon('shopping-basket')} Confirmar compra</button></div></div></div></section>`}
function purchases(){const items=buyerPurchases();return`<section class="content"><div class="row" style="margin-bottom:20px"><div><h2>Histórico de compras</h2><p class="muted">Consulte os pedidos realizados por este comprador.</p></div><span class="tag">${items.length} compra${items.length===1?'':'s'}</span></div>${items.length?`<div class="panel"><div class="list">${items.map(purchase=>`<div class="list-item"><div class="list-icon">${purchase.emoji||'🌱'}</div><div class="grow"><strong>${escapeHtml(purchase.product)}</strong><div class="muted">${escapeHtml(purchase.producer)} · ${purchase.quantity} ${escapeHtml(purchase.unit)}</div><div class="muted">${escapeHtml(purchase.date)}</div></div><div><strong>${money(purchase.total)}</strong><div class="muted">${money(purchase.price)}/${escapeHtml(purchase.unit)}</div></div></div>`).join('')}</div></div>`:`<div class="panel" style="text-align:center;padding:65px 20px"><div style="font-size:50px">🧺</div><h3>Nenhuma compra realizada</h3><p class="muted">Suas compras aparecerão aqui depois da confirmação.</p><button class="button" data-view="catalog">Explorar catálogo</button></div>`}</section>`}
function filteredCatalogOffers(){const text=(state.catalogFilters?.text||'').toLowerCase();const price=Number(state.catalogFilters?.price)||0;const availability=state.catalogFilters?.availability||'all';const harvest=state.catalogFilters?.harvest||'all';return availableOffers().filter(offer=>{const product=offer.productId?readProducts().find(item=>item.id===offer.productId):null;const quantity=product?Number(product.quantity):Number.parseFloat(String(offer.qty));const matchesText=!text||`${offer.name} ${offer.producer}`.toLowerCase().includes(text);const matchesPrice=!price||Number(offer.price)<=price;const matchesAvailability=availability==='all'||(availability==='available'&&quantity>0)||(availability==='unavailable'&&quantity<=0);const matchesHarvest=harvest==='all'||offer.harvest===harvest;return matchesText&&matchesPrice&&matchesAvailability&&matchesHarvest})}
function catalog(){state.catalogFilters=state.catalogFilters||{text:'',price:'',availability:'all',harvest:'all'};const harvests=[...new Set(availableOffers().map(offer=>offer.harvest).filter(Boolean))];return`<section class="content"><div class="row"><div><h2>Encontre ingredientes locais</h2><p class="muted">Compare preço, distância e disponibilidade em uma única tela.</p></div><span class="tag">${icon('map-pin')} Até 20 km de Viçosa</span></div><div class="filters"><input class="field" placeholder="Buscar produto..." value="${escapeHtml(state.catalogFilters.text)}" data-filter="text"><input class="field" type="number" min="0" step="0.01" placeholder="Preço máximo" value="${escapeHtml(state.catalogFilters.price)}" data-filter="price"><select class="select" data-filter="availability"><option value="all" ${state.catalogFilters.availability==='all'?'selected':''}>Qualquer disponibilidade</option><option value="available" ${state.catalogFilters.availability==='available'?'selected':''}>Disponível</option><option value="unavailable" ${state.catalogFilters.availability==='unavailable'?'selected':''}>Indisponível</option></select><select class="select" data-filter="harvest"><option value="all">Qualquer colheita</option>${harvests.map(date=>`<option value="${escapeHtml(date)}" ${state.catalogFilters.harvest===date?'selected':''}>${escapeHtml(date)}</option>`).join('')}</select></div><div class="grid grid-3" id="offer-list">${filteredCatalogOffers().map(offerCard).join('')||`<div class="panel"><h3>Nenhum produto encontrado</h3><p class="muted">Ajuste os filtros para ver outras ofertas.</p></div>`}</div></section>`}
function offerCard(offer){return`<article class="product-card"><div class="product-visual">${offer.emoji||'🌱'}</div><div class="product-info"><div class="row"><h3>${escapeHtml(offer.name)}</h3><span class="tag">${escapeHtml(offer.distance||'Viçosa')}</span></div><p class="muted">${escapeHtml(offer.producer)} · ${escapeHtml(offer.qty)}</p><p class="muted">Próxima colheita: ${escapeHtml(offer.harvest||'A combinar')}</p>${offer.description?`<p class="muted">${escapeHtml(offer.description)}</p>`:''}<div class="row"><span class="price">${money(Number(offer.price)||0)}<small>/${escapeHtml(offer.unit||'kg')}</small></span>${offer.productId?`<button class="button secondary" data-action="view-offer" data-product-id="${offer.productId}">Ver detalhes</button>`:`<button class="button secondary" data-offer="${escapeHtml(offer.name)}">Adicionar ao carrinho</button>`}</div></div></article>`}
function buyerApp(){const nav=buyerNav();if(state.view==='offer-detail')return shell(offerDetails(),'Detalhes do produto',nav);if(state.view==='purchases')return shell(purchases(),'Histórico de compras',nav);if(state.view==='catalog')return shell(catalog(),'Buscar ofertas',nav);if(state.view==='cart')return shell(cart(),'Seu carrinho',nav);if(state.view==='recurring')return shell(recurring(),'Compras recorrentes',nav);if(state.view==='profile')return shell(profile('comprador'),'Perfil da empresa',nav);return shell(buyerDashboard(),'Painel de compras',nav)}
function buyerDashboard(){const catalogOffers=availableOffers();return`<section class="content"><div class="hero"><div><span class="tag orange">${icon('sun')} Sazonal agora</span><h2>Colheita da semana na sua região</h2><p>Ingredientes frescos, de quem produz perto da sua cozinha.</p><br><button class="button large" data-view="catalog">${icon('search')} Explorar ofertas</button></div></div><div class="section-title"><h3>Colheita da semana</h3><button class="button ghost" data-view="catalog">Ver catálogo ${icon('arrow-right')}</button></div><div class="grid grid-3">${catalogOffers.slice(0,3).map(offerCard).join('')}</div><div class="grid grid-2" style="margin-top:22px"><div class="panel"><div class="panel-header"><div><h3>${icon('zap')} Excedentes disponíveis</h3><p class="muted">Oportunidades com preço especial hoje.</p></div><span class="tag orange">-20%</span></div><div class="list-item"><div class="list-icon">🥕</div><div class="grow"><strong>Cenoura</strong><div class="muted">Sítio Boa Vista · 90 kg</div></div><strong class="price">R$ 3,80/kg</strong></div></div><div class="panel"><h3>${icon('history')} Histórico de compras</h3><p class="muted">Veja os pedidos já realizados.</p><button class="button secondary full" data-view="purchases">Ver histórico</button></div></div></section>`}
app.addEventListener('input',event=>{if(event.target.matches('[data-login-input="email"]')&&state.role==='buyer')state.buyerEmail=event.target.value;if(event.target.matches('[data-purchase-quantity]')){const offer=buyerOffer(state.selectedProductId);const total=(Number(event.target.value)||0)*(Number(offer?.price)||0);const totalElement=document.querySelector('[data-purchase-total]');if(totalElement)totalElement.textContent=money(total)}if(event.target.matches('[data-filter]')){state.catalogFilters=state.catalogFilters||{};state.catalogFilters[event.target.dataset.filter]=event.target.value;const results=document.querySelector('#offer-list');if(results)results.innerHTML=filteredCatalogOffers().map(offerCard).join('')||'<div class="panel"><h3>Nenhum produto encontrado</h3><p class="muted">Ajuste os filtros para ver outras ofertas.</p></div>'}});
app.addEventListener('change',event=>{if(event.target.matches('[data-filter]')){state.catalogFilters=state.catalogFilters||{};state.catalogFilters[event.target.dataset.filter]=event.target.value;render()}});
app.addEventListener('click',event=>{const target=event.target.closest('[data-action]');const action=target?.dataset.action;if(action==='view-offer'){state.selectedProductId=target.dataset.productId;state.view='offer-detail';render()}if(action==='purchase'){const productId=target.dataset.productId;const product=readProducts().find(item=>item.id===productId);const offer=buyerOffer(productId);const quantity=Number(document.querySelector('[data-purchase-quantity]')?.value)||0;if(!product||!offer||quantity<=0){notify('Informe uma quantidade válida.');return}if(quantity>Number(product.quantity)){notify(`Quantidade insuficiente. Disponível: ${product.quantity} ${product.unit}.`);return}const total=quantity*Number(product.price);product.quantity=Number(product.quantity)-quantity;writeProducts(readProducts().map(item=>item.id===productId?product:item),{sync:false});const purchase={id:`purchase-${Date.now()}`,buyerEmail:buyerEmail(),producerEmail:product.producerEmail,producer:product.producer,productId:product.id,product:product.name,quantity,unit:product.unit,price:Number(product.price),total,date:new Date().toLocaleDateString('pt-BR'),emoji:productEmoji[product.name]||'🌱'};writePurchases([...readPurchases(),purchase]);state.selectedProductId=null;state.view='purchases';notify('Compra realizada com sucesso.');render()}});
app.addEventListener('input',event=>{if(event.target.matches('[data-login-input="email"]')&&state.role==='buyer')state.buyerEmail=event.target.value});
const savedBuyerEmail=localStorage.getItem('rurallink-buyer-email');if(savedBuyerEmail)state.buyerEmail=savedBuyerEmail;
app.addEventListener('click',event=>{if(event.target.closest('[data-action="login"]')&&state.role==='buyer'){state.buyerEmail=state.buyerEmail||'comprador@rurallink.com.br';localStorage.setItem('rurallink-buyer-email',state.buyerEmail)}});

const profileStorageKey='rurallink-profiles';
function readProfiles(){try{return JSON.parse(localStorage.getItem(profileStorageKey)||'{"producers":[],"buyers":[]}')}catch(error){return{producers:[],buyers:[]}}}
function writeProfiles(profiles){localStorage.setItem(profileStorageKey,JSON.stringify(profiles))}
function rememberProfile(role,profile){const profiles=readProfiles();const list=profiles[role]||[];const index=list.findIndex(item=>item.email===profile.email);if(index>=0)list[index]={...list[index],...profile};else list.push(profile);profiles[role]=list;writeProfiles(profiles);const services=backendServices();const service=role==='producers'?services?.produtorService:services?.compradorService;if(service)service.remember(profile).catch(()=>{})}
function producerRecords(){const profiles=readProfiles().producers||[];const products=readProducts();const purchases=readPurchases();const records=[...profiles];products.forEach(product=>{if(!records.some(record=>record.email===product.producerEmail))records.push({email:product.producerEmail,name:product.producer||'Produtor Rural',whatsapp:'Código WhatsApp simulado'})});purchases.forEach(purchase=>{if(!records.some(record=>record.email===purchase.producerEmail))records.push({email:purchase.producerEmail,name:purchase.producer||'Produtor Rural',whatsapp:'Código WhatsApp simulado'})});return records}
function buyerRecords(){const profiles=readProfiles().buyers||[];const purchases=readPurchases();const records=[...profiles];purchases.forEach(purchase=>{if(!records.some(record=>record.email===purchase.buyerEmail))records.push({email:purchase.buyerEmail,name:purchase.buyer||purchase.buyerEmail})});return records}
function adminProducts(){return readProducts()}
function adminProductStatus(product){const quantity=Number(product.quantity)||0;return quantity<=0?'Indisponível':quantity<=10?'Estoque baixo':'Disponível'}
function adminSearch(value){return String(value||'').toLowerCase().trim()}
function adminPanelHeader(title,description,searchKey,placeholder){return`<div class="panel-header"><div><h3>${title}</h3><p class="muted">${description}</p></div>${searchKey?`<input class="field" style="max-width:280px" placeholder="${placeholder}" value="${escapeHtml(state.adminSearch?.[searchKey]||'')}" data-admin-search="${searchKey}">`:''}</div>`}
function adminSummary(){const products=adminProducts();const purchases=readPurchases();const producerCount=producerRecords().length;const buyerCount=buyerRecords().length;const total= purchases.reduce((sum,purchase)=>sum+Number(purchase.total||0),0);return{producerCount,buyerCount,productCount:products.length,purchaseCount:purchases.length,total,availableCount:products.filter(product=>Number(product.quantity)>0).length}}
function adminDashboard(){const summary=adminSummary();return`<section class="content"><div class="grid grid-3"><div class="panel stat"><span class="muted">Produtores cadastrados</span><strong>${summary.producerCount}</strong></div><div class="panel stat"><span class="muted">Compradores cadastrados</span><strong>${summary.buyerCount}</strong></div><div class="panel stat"><span class="muted">Produtos cadastrados</span><strong>${summary.productCount}</strong></div><div class="panel stat"><span class="muted">Compras realizadas</span><strong>${summary.purchaseCount}</strong></div><div class="panel stat"><span class="muted">Valor total das compras</span><strong>${money(summary.total)}</strong></div><div class="panel stat"><span class="muted">Produtos disponíveis</span><strong>${summary.availableCount}</strong></div></div><div class="grid grid-2" style="margin-top:22px"><div class="panel"><div class="panel-header"><div><h3>Resumo da operação</h3><p class="muted">Dados atuais da plataforma.</p></div><span class="tag">Dados reais</span></div><div class="list-item"><div class="list-icon">🌱</div><div class="grow"><strong>${summary.productCount} produtos</strong><div class="muted">${summary.availableCount} com estoque disponível</div></div><button class="button secondary" data-view="admin-products">Ver produtos</button></div><div class="list-item"><div class="list-icon">🧺</div><div class="grow"><strong>${summary.purchaseCount} compras</strong><div class="muted">${money(summary.total)} movimentados</div></div><button class="button secondary" data-view="admin-purchases">Ver compras</button></div></div><div class="panel"><h3>Atalhos administrativos</h3><div class="list"><button class="list-item" data-view="admin-producers"><div class="list-icon">${icon('sprout')}</div><div class="grow"><strong>Produtores</strong><div class="muted">Consultar cadastros e produtos</div></div>${icon('chevron-right')}</button><button class="list-item" data-view="admin-buyers"><div class="list-icon">${icon('store')}</div><div class="grow"><strong>Compradores</strong><div class="muted">Consultar compras e totais</div></div>${icon('chevron-right')}</button></div></div></div></section>`}
function adminProducers(){const query=adminSearch(state.adminSearch?.producers);const records=producerRecords().filter(record=>`${record.name} ${record.email}`.toLowerCase().includes(query));return`<section class="content"><div class="panel">${adminPanelHeader('Produtores','Todos os produtores relacionados aos produtos e compras da plataforma.','producers','Pesquisar produtor ou e-mail')}${records.length?records.map(record=>{const products=adminProducts().filter(product=>product.producerEmail===record.email);return`<div class="list-item"><div class="list-icon">${icon('sprout')}</div><div class="grow"><strong>${escapeHtml(record.name)}</strong><div class="muted">${escapeHtml(record.email)} · ${escapeHtml(record.whatsapp||'Código WhatsApp simulado')}</div><div class="muted">${products.length} produto${products.length===1?'':'s'} cadastrado${products.length===1?'':'s'}</div></div><button class="button secondary" data-action="admin-producer" data-email="${escapeHtml(record.email)}">Ver produtos</button></div>`}).join(''):`<p class="muted">Nenhum produtor encontrado.</p>`}</div></section>`}
function adminProducerDetail(){const email=state.adminSelectedEmail;const record=producerRecords().find(item=>item.email===email);const products=adminProducts().filter(product=>product.producerEmail===email);return`<section class="content"><button class="button ghost" data-view="admin-producers">${icon('arrow-left')} Voltar aos produtores</button><div class="panel" style="margin-top:20px">${adminPanelHeader(record?.name||'Produtor','Produtos cadastrados por este produtor.')}${record?`<p class="muted">${escapeHtml(record.email)} · ${escapeHtml(record.whatsapp||'Código WhatsApp simulado')}</p>`:''}<div class="list">${products.length?products.map(product=>`<div class="list-item"><div class="list-icon">${productEmoji[product.name]||'🌱'}</div><div class="grow"><strong>${escapeHtml(product.name)}</strong><div class="muted">${product.quantity} ${escapeHtml(product.unit)} · ${money(Number(product.price))}/${escapeHtml(product.unit)}</div><div class="muted">Próxima colheita: ${escapeHtml(product.harvest||'A combinar')}</div></div><span class="tag ${adminProductStatus(product)==='Indisponível'?'red':''}">${adminProductStatus(product)}</span></div>`).join(''):`<p class="muted">Nenhum produto cadastrado.</p>`}</div></div></section>`}
function adminBuyers(){const query=adminSearch(state.adminSearch?.buyers);const records=buyerRecords().filter(record=>`${record.name} ${record.email}`.toLowerCase().includes(query));return`<section class="content"><div class="panel">${adminPanelHeader('Compradores','Todos os compradores que acessaram ou realizaram compras.','buyers','Pesquisar comprador ou e-mail')}${records.length?records.map(record=>{const purchases=readPurchases().filter(purchase=>purchase.buyerEmail===record.email);const total=purchases.reduce((sum,purchase)=>sum+Number(purchase.total||0),0);return`<div class="list-item"><div class="list-icon">${icon('store')}</div><div class="grow"><strong>${escapeHtml(record.name)}</strong><div class="muted">${escapeHtml(record.email)}</div><div class="muted">${purchases.length} compra${purchases.length===1?'':'s'} · ${money(total)}</div></div><button class="button secondary" data-action="admin-buyer" data-email="${escapeHtml(record.email)}">Ver histórico</button></div>`}).join(''):`<p class="muted">Nenhum comprador encontrado.</p>`}</div></section>`}
function adminBuyerDetail(){const email=state.adminSelectedEmail;const record=buyerRecords().find(item=>item.email===email);const purchases=readPurchases().filter(purchase=>purchase.buyerEmail===email);return`<section class="content"><button class="button ghost" data-view="admin-buyers">${icon('arrow-left')} Voltar aos compradores</button><div class="panel" style="margin-top:20px">${adminPanelHeader(record?.name||'Comprador','Histórico de compras deste comprador.')}${record?`<p class="muted">${escapeHtml(record.email)}</p>`:''}<div class="list">${purchases.length?purchases.map(purchase=>`<div class="list-item"><div class="list-icon">${purchase.emoji||'🌱'}</div><div class="grow"><strong>${escapeHtml(purchase.product)}</strong><div class="muted">${escapeHtml(purchase.producer)} · ${purchase.quantity} ${escapeHtml(purchase.unit)}</div><div class="muted">${escapeHtml(purchase.date)}</div></div><strong>${money(Number(purchase.total))}</strong></div>`).join(''):`<p class="muted">Nenhuma compra realizada.</p>`}</div></div></section>`}
function adminProductsPage(){const query=adminSearch(state.adminSearch?.products);const products=adminProducts().filter(product=>`${product.name} ${product.producer} ${product.producerEmail}`.toLowerCase().includes(query));return`<section class="content"><div class="panel">${adminPanelHeader('Produtos da plataforma','Estoque e situação atual de cada produto.','products','Pesquisar produto ou produtor')}${products.length?products.map(product=>`<div class="list-item"><div class="list-icon">${productEmoji[product.name]||'🌱'}</div><div class="grow"><strong>${escapeHtml(product.name)}</strong><div class="muted">${escapeHtml(product.producer)} · ${product.quantity} ${escapeHtml(product.unit)}</div><div class="muted">${money(Number(product.price))}/${escapeHtml(product.unit)} · Colheita: ${escapeHtml(product.harvest||'A combinar')}</div></div><span class="tag ${adminProductStatus(product)==='Indisponível'?'red':''}">${adminProductStatus(product)}</span></div>`).join(''):`<p class="muted">Nenhum produto encontrado.</p>`}</div></section>`}
function adminPurchases(){const query=adminSearch(state.adminSearch?.purchases);const purchases=readPurchases().filter(purchase=>`${purchase.buyerEmail} ${purchase.buyer||''} ${purchase.producer} ${purchase.product}`.toLowerCase().includes(query));return`<section class="content"><div class="panel">${adminPanelHeader('Compras realizadas','Histórico real de compras da plataforma.','purchases','Pesquisar compra')}${purchases.length?`<div class="list">${purchases.map(purchase=>`<div class="list-item"><div class="list-icon">${purchase.emoji||'🌱'}</div><div class="grow"><strong>${escapeHtml(purchase.product)}</strong><div class="muted">Comprador: ${escapeHtml(purchase.buyer||purchase.buyerEmail)}</div><div class="muted">Produtor: ${escapeHtml(purchase.producer)} · ${purchase.quantity} ${escapeHtml(purchase.unit)}</div><div class="muted">${escapeHtml(purchase.date)} · ${money(Number(purchase.price))}/${escapeHtml(purchase.unit)}</div></div><strong>${money(Number(purchase.total))}</strong></div>`).join('')}</div>`:`<p class="muted">Nenhuma compra encontrada.</p>`}</div></section>`}
const adminNavigation=[['dashboard','Dashboard','layout-dashboard'],['admin-producers','Produtores','sprout'],['admin-buyers','Compradores','store'],['admin-products','Produtos','package'],['admin-purchases','Compras','shopping-basket'],['users','Cadastros','users'],['moderation','Moderação','shield-check'],['routes','Rotas','route'],['production','Produção local','sprout']];
function adminApp(){if(state.view==='admin-producers')return shell(adminProducers(),'Produtores',adminNavigation);if(state.view==='admin-producer-detail')return shell(adminProducerDetail(),'Detalhes do produtor',adminNavigation);if(state.view==='admin-buyers')return shell(adminBuyers(),'Compradores',adminNavigation);if(state.view==='admin-buyer-detail')return shell(adminBuyerDetail(),'Detalhes do comprador',adminNavigation);if(state.view==='admin-products')return shell(adminProductsPage(),'Produtos',adminNavigation);if(state.view==='admin-purchases')return shell(adminPurchases(),'Compras',adminNavigation);if(state.view==='users')return shell(adminUsers(),'Cadastros pendentes',adminNavigation);return shell(adminDashboard(),'Visão geral',adminNavigation)}
app.addEventListener('input',event=>{if(event.target.matches('[data-login-input="email"]')&&state.role==='producer'){state.producerEmail=event.target.value;rememberProfile('producers',{email:state.producerEmail,name:'Produtor Rural',whatsapp:'Código WhatsApp simulado'})}if(event.target.matches('[data-login-input="email"]')&&state.role==='buyer'){state.buyerEmail=event.target.value;rememberProfile('buyers',{email:state.buyerEmail,name:'Comprador'})}if(event.target.matches('[data-admin-search]')){state.adminSearch=state.adminSearch||{};state.adminSearch[event.target.dataset.adminSearch]=event.target.value;render()}});
app.addEventListener('click',event=>{const target=event.target.closest('[data-action]');const action=target?.dataset.action;if(action==='admin-producer'){state.adminSelectedEmail=target.dataset.email;state.view='admin-producer-detail';render()}if(action==='admin-buyer'){state.adminSelectedEmail=target.dataset.email;state.view='admin-buyer-detail';render()}if(action==='verify-code'&&state.role==='producer'){rememberProfile('producers',{email:state.producerEmail||'produtor@rurallink.com.br',name:'Produtor Rural',whatsapp:'Código WhatsApp simulado'})}if(action==='login'&&state.role==='buyer'){rememberProfile('buyers',{email:state.buyerEmail||'comprador@rurallink.com.br',name:'Comprador'})}});
async function hydrateFromBackend(){const services=backendServices();if(!services)return;try{const [products,purchases,producers,buyers]=await Promise.all([services.produtoService.list(),services.compraService.list(),services.produtorService.list(),services.compradorService.list()]);localStorage.setItem(productStorageKey,JSON.stringify(products));localStorage.setItem(purchaseStorageKey,JSON.stringify(purchases));localStorage.setItem('rurallink-profiles',JSON.stringify({producers,buyers}))}catch(error){}}
hydrateFromBackend().finally(render);